<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('reports.view');$from=(string)input('from',date('Y-m-d',strtotime('-30 days')));$to=(string)input('to',date('Y-m-d'));if(!valid_date($from)||!valid_date($to)){flash('error','Invalid report date range.');$from=date('Y-m-d',strtotime('-30 days'));$to=date('Y-m-d');}$stmt=db()->prepare('SELECT COALESCE(u.name,"System/Admin") user_name,s.event_type,s.ip_address,s.device_id,s.risk_level,s.description,s.created_at FROM security_events s LEFT JOIN users u ON u.id=s.user_id WHERE s.created_at>=? AND s.created_at<DATE_ADD(?,INTERVAL 1 DAY) ORDER BY s.id DESC LIMIT 5000');$stmt->execute([$from,$to]);$rows=$stmt->fetchAll();if(input('export')==='csv'){require_permission('reports.export');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="security-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['User','Event','IP','Device','Risk','Description','Date'],',','"','\\');foreach($rows as $r)fputcsv($out,csv_row($r),',','"','\\');audit_log((int)admin()['id'],'REPORT_EXPORT','reports','security',null,['from'=>$from,'to'=>$to,'rows'=>count($rows)]);exit;}$pageTitle='Security report';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><h2>Security activity</h2><div class="actions"><a href="<?=e(app_url('/admin/reports/users.php'))?>">Users</a><a href="<?=e(app_url('/admin/reports/withdrawals.php'))?>">Withdrawals</a></div></div><form class="filters"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Run report</button><?php if(can('reports.export')):?><button class="btn secondary" name="export" value="csv">Export CSV</button><?php endif?></form><div class="table-wrap"><table><thead><tr><th>User</th><th>Event</th><th>IP</th><th>Device</th><th>Risk</th><th>Description</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['user_name'])?></td><td><?=e($r['event_type'])?></td><td><?=e($r['ip_address']??'—')?></td><td><?=e($r['device_id']??'—')?></td><td><?=e($r['risk_level'])?></td><td><?=e($r['description'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
